{
  "user_request": "Primeiro capítulo de um isekai manhwa bem diferenciado em relação à história, diferente do convencional.",
  "audience": "Leitores de manhwa/webnovel que gostam de isekai, metalinguagem, fantasia sombria e subversão de tropes.",
  "tone": "cinematográfico, estranho, tenso, metalinguístico, com humor amargo discreto.",
  "rating": "teen/adult light",
  "output": [
    "markdown",
    "json",
    "work-corpus"
  ],
  "provisional_suggestions": {
    "pov": "terceira pessoa próxima centrada em Davi",
    "tense": "passado",
    "differentiator": "O protagonista não reencarna como herói ou vilão; ele acorda como a margem textual de uma light novel e consegue alterar frases, comentários de revisão e versões descartadas."
  }
}

[
  {
    "name": "Davi Noh",
    "role": "protagonista / consciência presa na margem",
    "desire": "Sobreviver à correção da página e impedir que personagens sejam esmagados por funções narrativas.",
    "need": "Assumir responsabilidade pelas histórias que ajudou a moldar.",
    "flaw": "Costuma reduzir pessoas a estrutura, função e eficiência.",
    "power": "Editar frases, inserir palavras mínimas, deslocar peso narrativo, recuperar versões cortadas e interferir em comentários de revisão.",
    "limitation": "Não tem corpo dentro da história e não pode criar do nada; age como revisor, não como autor absoluto."
  },
  {
    "name": "Yerin",
    "role": "princesa amaldiçoada / primeira personagem que percebe a margem",
    "desire": "Não morrer como gatilho emocional da história de outra pessoa.",
    "need": "Transformar sobrevivência em escolha própria.",
    "state_after_chapter_1": "Ferida no ombro, viva, fugiu pelo canal inferior usando uma variação descartada do roteiro."
  },
  {
    "name": "Kael",
    "role": "herói regressor original / antagonista estrutural inicial",
    "desire": "Restaurar a narrativa em que ele chega no momento perfeito e centraliza todos os eventos.",
    "threat": "Consegue perceber a margem, escrever comentários de revisão e bloquear permissões de escrita."
  },
  {
    "name": "Assassino da Casa Baek",
    "role": "executante da cena original / entidade possivelmente consciente",
    "state_after_chapter_1": "Percebeu Davi e identificou-o como 'leitor'."
  }
]

[
  {
    "pair": [
      "Davi",
      "Yerin"
    ],
    "dynamic": "Contato impossível entre margem e personagem; Davi altera enquadramentos para devolver agência a Yerin, mas corre o risco de manipulá-la de outra forma."
  },
  {
    "pair": [
      "Davi",
      "Kael"
    ],
    "dynamic": "Conflito entre editor invisível e herói absoluto que acredita possuir a página."
  }
]

{
  "setting": "A light novel/manhwa A Lança do Imperador Regressor, com reino chuvoso, casas nobres, maldições, margens textuais, notas de revisão, comentários e versões cortadas como camadas reais.",
  "rules": [
    "A margem textual é um espaço real onde Davi existe como consciência sem corpo.",
    "A versão publicada, notas de revisão, comentários e variações descartadas são camadas distintas da história.",
    "Davi pode alterar causalidade com pequenas revisões, mas não pode criar livremente do nada.",
    "A página tenta restaurar cenas obrigatórias e relações principais quando a narrativa se desvia.",
    "Personagens com autoria devolvida por falas cortadas podem alcançar parcialmente a margem."
  ]
}

[
  {
    "chapter": 1,
    "title": "O Homem na Margem da Página",
    "purpose": "Apresentar Davi como revisor preso na margem textual, Yerin como personagem que recupera agência e Kael como herói que chega tarde e invade a margem."
  },
  {
    "chapter": 2,
    "title": "Resolver Conversa",
    "purpose": "Transformar comentários de revisão em ameaça, devolver uma fala cortada a Yerin e estabelecer o Pavilhão dos Arquivos como próximo destino."
  },
  {
    "chapter": 3,
    "title": "O Pavilhão dos Arquivos",
    "purpose": "Explorar versões descartadas, registros de revisão e as consequências de Yerin tocar a margem."
  }
]

[
  {
    "id": "chapter-001-light-novel-created",
    "note": "Canonical chapter 1 kept as light novel/webnovel version."
  },
  {
    "id": "chapter-002-light-novel-created",
    "note": "Created chapter 2 and enriched the work corpus with chapter memory sections."
  },
  {
    "id": "cleanup-before-git",
    "note": "Removed old manhwa draft artifacts and normalized project bible to the light novel continuity."
  }
]

{
  "character_states": [
    {
      "name": "Davi Noh",
      "state": "Consciência sem corpo presa à margem textual; entende que revisão pode alterar destino se entrar discretamente nas frases."
    },
    {
      "name": "Yerin",
      "state": "Ferida no ombro, viva, fugiu pelo canal inferior e manteve agência própria."
    },
    {
      "name": "Kael",
      "state": "Herói regressor frustrado; percebe a margem e escreve comentários fora do texto."
    }
  ],
  "relationship_changes": [
    {
      "pair": [
        "Davi",
        "Yerin"
      ],
      "change": "Davi devolve possibilidades cortadas a Yerin, mas precisa evitar substituir a vontade dela pela dele."
    },
    {
      "pair": [
        "Davi",
        "Kael"
      ],
      "change": "Kael identifica Davi como interferência editorial e ameaça disputar a margem."
    }
  ]
}

{
  "character_states": [
    {
      "name": "Davi Noh",
      "state": "Continua sem corpo na margem; aprende que não deve apenas decidir por Yerin e descobre a regra de autoria das falas cortadas."
    },
    {
      "name": "Yerin",
      "state": "Ferida, viva, com o selo da carruagem; foge para o Pavilhão dos Arquivos e passa a tocar parcialmente a margem por meio de uma fala recuperada."
    },
    {
      "name": "Kael",
      "state": "Controla comentários na margem, bloqueia permissões e entende que a autoria devolvida a Yerin ameaça sua posse narrativa."
    },
    {
      "name": "Assassino da Casa Baek",
      "state": "Mostra submissão a Kael e age como agente de correção da cena, tentando impedir a fuga de Yerin."
    }
  ],
  "relationship_changes": [
    {
      "pair": [
        "Davi",
        "Yerin"
      ],
      "change": "Yerin recebe uma fala cortada de volta, mas exige que Davi pare de decidir por ela."
    },
    {
      "pair": [
        "Davi",
        "Kael"
      ],
      "change": "Kael bloqueia Davi na margem e propõe uma disputa direta de revisão."
    },
    {
      "pair": [
        "Yerin",
        "Kael"
      ],
      "change": "Yerin rejeita a posição de resgatada e critica Kael por chegar tarde."
    }
  ]
}
